def run(context):
    risk_flags = []
    for record in context['equity_data']:
        if record['rsi'] > 70 or record['trend_signal'] == 'BEARISH':
            risk_flags.append(record['symbol'])
    return risk_flags

def run(context):
    # Analyze interactions among trends
    risk_categorization = []
    for row in context:
        if row['regime'] == 'BULL' and row['flow_signal'] == 'STRONG_BUY':
            risk_categorization.append('Risk-On')
        else:
            risk_categorization.append('Risk-Off')
    return risk_categorization
